INSERT OR IGNORE INTO portal_profile_history(id,slug,before_data,after_data,reason,admin_hash) VALUES('0059-image-kumicho','kumicho','{"slug":"kumicho","displayName":"ガチ経営者VTuber組長","description":"皆さんこんばんは。\n\nガチ経営者VTuber組長です。\n\n高校中退。\n\n18歳で清掃業界に入り、\n29歳で独立しました。\n\n今は官公庁の仕事を中心に、\n清掃会社を経営しています。\n\nこのチャンネルでは、\n経営、営業、お金、採用、\nそして独立について、\n綺麗事なしでお話ししていきます。\n\n学歴もコネもありませんでした。\n\nだからこそ、\n普通の人がどうやって人生を切り開くのか。\n\nその挑戦の過程を発信していきます。\n\nそれでは皆さん、\n今日も未来の自分に乾杯🍻\n\nFA→＃ガチ経営者VTuber組長\nファンネーム：#若頭\nファンマーク：🕶️\n配信タグ：#組長会議\n切り抜き：#組長の教え\nファンアート：#組長画報\n\nチャンネル登録者数×1,000円を慈善団体に寄付します\nだから1,000人で100万円寄付です\n寄付する先は栃木の養護施設です　友人が関わっているので安心です\nさあ、俺の話を聞きたい人あつまれ\nマシュマロ質問箱→https://marshmallow-qa.com/me\nXアカウント→https://x.com/birukanriumeki\n有限会社名阪ビル管理　https://www.nagoya1-eco.jp/\n","avatarUrl":"https://yt3.googleusercontent.com/mUDgI890xnDrw2rh8hJvgXDqy1KDw-rWMDOjU8I74dfot9aH25MxnXZxT4crcLIeE5_SURo1=s900-c-k-c0x00ffffff-no-rj","agency":"개인세","platform":"YOUTUBE","channelUrl":"https://www.youtube.com/channel/UCpQje3p1s3BiPEp3MVm76hQ","countryCode":"JP","languages":[],"tags":[],"xUrl":"","dateState":"FIXED","debutDate":"2026-08-31","debutTime":"20:00","timezone":"Asia/Seoul","startAtUtc":"2026-08-31T11:00:00.000Z","targetMonth":"2026-08","ownerVerified":false,"source":"EXISTING"}','{"slug":"kumicho","displayName":"ガチ経営者VTuber組長","description":"皆さんこんばんは。\n\nガチ経営者VTuber組長です。\n\n高校中退。\n\n18歳で清掃業界に入り、\n29歳で独立しました。\n\n今は官公庁の仕事を中心に、\n清掃会社を経営しています。\n\nこのチャンネルでは、\n経営、営業、お金、採用、\nそして独立について、\n綺麗事なしでお話ししていきます。\n\n学歴もコネもありませんでした。\n\nだからこそ、\n普通の人がどうやって人生を切り開くのか。\n\nその挑戦の過程を発信していきます。\n\nそれでは皆さん、\n今日も未来の自分に乾杯🍻\n\nFA→＃ガチ経営者VTuber組長\nファンネーム：#若頭\nファンマーク：🕶️\n配信タグ：#組長会議\n切り抜き：#組長の教え\nファンアート：#組長画報\n\nチャンネル登録者数×1,000円を慈善団体に寄付します\nだから1,000人で100万円寄付です\n寄付する先は栃木の養護施設です　友人が関わっているので安心です\nさあ、俺の話を聞きたい人あつまれ\nマシュマロ質問箱→https://marshmallow-qa.com/me\nXアカウント→https://x.com/birukanriumeki\n有限会社名阪ビル管理　https://www.nagoya1-eco.jp/\n","avatarUrl":"https://yt3.googleusercontent.com/obynWlFuwMeQSPXlePBYBf2pIduvEhOjsytBzV9C2MNMnSSPySBq-QysJtMeQ